import "./VerbTable.css";
import React, { useState } from "react";
import { GloballyExpanded } from "../App";

export interface VerbTense {
  header: string;
  conjugations: string[];
}

export interface VerbTableProps {
  title: string;
  verbs: VerbTense[];
  row_labels?: string[];
}

interface LocallyExpanded {
  expanded: boolean;
  overrideActionCount: number;
}

export function VerbTable({
  title,
  verbs,
  row_labels,
  globallyExpanded,
}: VerbTableProps & { globallyExpanded: GloballyExpanded }) {
  const [locallyExpanded, setLocallyExpanded] = useState<LocallyExpanded>({
    expanded: false,
    overrideActionCount: 0,
  });

  const leftCol: VerbTense = {
    header: "",
    conjugations: row_labels || ["yo", "tu", "ello/a", "nosotros", "ellos"],
  };
  verbs = [leftCol, ...verbs];
  const headers = verbs.map((verb) => verb.header);
  let rows: string[][] = verbs[0].conjugations.map(() => []);
  verbs.forEach((verb) => {
    verb.conjugations.forEach((conjugation, i) => {
      rows[i].push(conjugation);
    });
  });

  const expanded =
    locallyExpanded.overrideActionCount >= globallyExpanded.actionCount
      ? locallyExpanded.expanded
      : globallyExpanded.expanded;
  console.log(`Rendering with expanded ${expanded}`);
  return (
    <details className={"verb-collapsable"} open={expanded}>
      <summary
        onClick={(e) => {
          e.preventDefault();
          console.log(`Setting locally expanded to ${!expanded}`);
          setLocallyExpanded({
            expanded: !expanded,
            overrideActionCount: globallyExpanded.actionCount,
          });
        }}
      >
        {title}
      </summary>

      <table className={"verb-table"}>
        <tbody>
          <tr>
            {headers.map((header) => (
              <th key={header}>{header}</th>
            ))}
          </tr>
          {rows.map((row, rowIdx) => (
            <tr key={rowIdx}>
              {row.map((conjugation, idx) => (
                <td key={`${headers[idx]}-${conjugation}`}>{conjugation}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </details>
  );
}
